export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:00。M 區。小會議室。會議結束以後，走廊那端的房間被重新整理過。摺疊桌收了。換成兩張長桌。一張放筆電。一張放證物。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上是 KAGAMI 硬體登錄庫。不是決策介面。不是依存圖。是另一種畫面。序號。型號。安全晶片狀態。歸還記錄。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在長桌的一側。她的面前放著會議記錄副本。她沒有翻開。日下部坐在對面。千田坐在他旁邊。指定專家站在螢幕前。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:05。指定專家把第一份資料拉到螢幕中央。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "KAGAMI 原始簽署載體。硬體功能、唯一序號、不可匯出的簽署金鑰、安全晶片 attestation。KAGAMI-01／OFFLINE_LOCAL_AUTH。預簽署套件驗證。斷網下重開本地準備及部分 COMMIT-GATE 權限。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "它不能單獨啟動全部公共系統、不能繞過所有物理安全、不能直接控制 M-00。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看了一眼千田。千田點頭。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "但與本地預簽署套件、emergency override、鏡島現場存取結合時——足以恢復重大風險。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:10。指定專家切換畫面。遠端醫療節點的合法用途。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "原始載體在遠端醫療節點有一項合法表面用途。臨床影子參照重新註冊的根憑證。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他展開細節。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "用途——更換本地控制器。更新本地影子模型。恢復安全晶片。驗證與 M-00 的來源鏈。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "遠端節點只能讀取硬體身分、完成影子參照註冊、記錄 attestation。不能啟動鏡島、不能提交公共 fanout、不能使用完整本地授權。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）合法用途。所以載體出現在醫院節點——本身不構成犯罪。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上的欄位還亮著。合法用途的清單。換控制器。更新影子模型。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）這些都是真的會發生的維護工作。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著那個清單。沒有翻開面前的會議記錄。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）問題不在於它能不能出現在那裡。問題在於——它為什麼出現。有沒有工作單。有沒有借出紀錄。出現以後——有沒有回去。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:15。指定專家切換到下一頁。登錄庫的借出與歸還欄。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "安全庫借出紀錄。查詢結果——無。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上那一欄是空的。不是「已歸還」。不是「借出中」。是沒有紀錄。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "對應工作單。查詢結果——無。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "也是空的。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "attestation nonce 範圍。普通影子參照註冊——nonce 落在標準區間。美空節點記錄的 nonce——超出標準區間。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著日下部。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "安全庫沒有收到同封條號的歸還物。之後載體下落不明。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "記錄。無借出。無工作單。nonce 異常。未歸還。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在證物清單上寫下四行。簽名。時間戳。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "使用時間。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "使用時間——在封緘失蹤之後。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯失蹤以後才出現。沒有借出。沒有工作單。nonce 超出範圍。用了以後沒有還。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有提高聲音。她在陳述。像在讀查核報告。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "合法用途存在。但這一次的使用——不符合合法用途的程序條件。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "技術上成立。合法用途的程序條件包括——借出紀錄、工作單、nonce 在標準區間、使用後歸還。本次使用——四項均不符合。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:25。指定專家切換畫面。封緘證據。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "維護交接紀錄。20:40。一枚 KAGAMI 原始簽署載體進入交接區。千田因受到保護未前往領取。21:04。維修服人物以表面有效權限處理一件封緘物。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他調出便衣拍攝的影像。不是高清照片。是監視器截圖。光線不好。角度偏。但形制看得見。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "便衣記錄。薄銀色防靜電外殼。雙卡扣。一側細長指示窗。工具箱。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "截圖被放大。銀色。很薄。邊緣有卡扣。一側有一條細長的窗。像指示燈的位置。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後指定專家切換到當輪庫存資料。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "當輪 KAGAMI 庫存影像。同型載體。薄銀色防靜電外殼、雙卡扣、細長指示窗。接口位置——左側偏下。邊角形制——圓角。與封緘當晚便衣記錄的形制高度吻合。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兩組影像並排。一組是便衣在昏暗交接區拍的。一組是庫存資料裡的標準照。光線不同。角度不同。但外殼的形狀、卡扣的位置、指示窗的比例——像同一個模子。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "第一輪。我交給她的那個。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田的聲音很低。他看著螢幕。看著那個銀色外殼。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "薄銀色。防靜電。雙卡扣。一側有細長的指示窗。邊緣鋒利。上面有血。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "我從安全庫取出來的時候——沒有登記。我繞過了借出程序。因為我已經知道他們會改監視器。我沒有時間走正常流程。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他也是。他也是繞過程序的。不是因為他想犯罪。是因為他知道自己只剩一次機會。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田沒有抬頭。他看著螢幕上那個銀色外殼。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——繞過程序的人留下的痕跡，和故意掩蓋的人留下的痕跡，在系統裡看起來一樣。無借出。無工作單。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢光燈嗡嗡地響。會議室裡沒有別的聲音。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）差別只在動機。而系統不記錄動機。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:35。指定專家把跨輪證據也調出來了。但放在螢幕下方。不是主畫面。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "跨輪草圖證據。第一輪——記憶的草圖。第三輪早晨——封緘重畫。兩者均為記憶重製。不是直接證據。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兩張草圖。一張是第一輪澪憑記憶畫的。一張是第三輪早晨在看到當輪庫存影像以前封緘重畫的。銀色。薄。雙卡扣。細長窗。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "草圖與當輪庫存型號高度吻合。但草圖證據等級——低於當輪硬體資料。記憶重製不能證明同一序號。不能證明同一實物。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "正式結論。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "千田第一輪交給朝倉澪的銀色外殼——高概率是同型 KAGAMI 原始簽署載體。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。很清楚的一頓。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "不能證明——同一序號、現在由特定人持有、第一輪與第三輪為同一物理實物。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "同型。高概率。不是同一個。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "是。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）同型。不是同一個。我手上的那個——第一輪的——沒有跟回來。現在的這個——是第三輪庫存裡的同型。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兩組影像還並排在螢幕上。同一個形制。同一個型號。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）草圖是我的記憶。記憶不能證明序號。可是——形制吻合。雙卡扣。細長窗。圓角。接口位置。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田的聲音很低。他看著螢幕。他從安全庫拿出來過。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他認得那個外殼。他說——就是那個。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:45。日下部把證物清單更新了一頁。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "缺失載體。唯一硬體序號——已記錄。attestation——已記錄。封緘證據——已記錄。第一輪銀色外殼形制——與當輪同型高概率吻合。跨輪草圖——證據等級低於當輪硬體資料。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他簽名。時間戳。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "下一步。鏡島。剩餘攻擊面。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:50。指定專家切換到鏡島的架構圖。東京灣人工島。KAGAMI-01 的節點位置。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "鏡島不能完全關閉。仍承擔——真實公共安全。原始訊號過濾。臨床閉環。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "圖上標著幾個入口。主入口。維護入口。緊急維護入口。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "人工島設有獨立緊急維護入口。與主入口分開。獨立電源。獨立門禁。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "合法承包班次。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "合法承包班次仍須進場。鏡島的公共安全與過濾功能不能中斷。維護人員需要定期進入。緊急維護入口在非維護時段處於封閉狀態。但維護時段——有合法人員在場。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "缺失載體可以將普通維護終端提升為本地授權終端。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "意思是——有人帶著載體進入維護入口。把普通終端升級。就能取得 KAGAMI-01 本地授權。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "技術上成立。普通維護終端——只有基本讀取權限。插入原始簽署載體後——終端讀取硬體身分、讀取 attestation。如果 nonce 通過——終端被提升為本地授權。可以執行離線本地準備、操作部分 COMMIT-GATE。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看了一眼日下部。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "不能單獨啟動公共 fanout。但能為 emergency override 提供本地授權基礎。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "21:04 共享臨時卡承包鏈。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "21:04 的共享臨時卡承包鏈——是可接觸該緊急維護入口的維護鏈之一。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他調出班次表。21:04。共享臨時卡。承包商名稱。人員名單。部分遮蔽。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "共享臨時卡——不綁定特定人員。任何持有該卡的人都能在該時段進入維護入口。卡的使用紀錄只顯示卡號。不顯示持卡人。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯不綁定人員。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "是。共享臨時卡的設計目的是——讓外包承包商的流動人員能在不同班次進入。不需要逐一登記。卡號統一。人員不統一。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不綁定人員。所以 21:04 那張卡——誰用的——系統不記錄。只知道卡號。不知道人。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "班次表上的人員名單部分遮蔽。卡號清楚。人不清楚。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）又是——看不到人。又是——只有代碼。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "21:00。日下部在證物清單上新增一頁。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "鏡島剩餘攻擊面。緊急維護入口——獨立門禁。合法承包班次——仍須進場。共享臨時卡——不綁定人員。缺失載體——可升級普通終端為本地授權終端。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "物理監看。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "物理監看可以降低風險。在維護時段派員監看緊急維護入口。記錄進出人員。核對身份。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "但不能消除風險。合法承包人員仍須進場。共享臨時卡仍可使用。如果缺失載體被帶入——物理監看能記錄、能延遲，但不能阻止合法維護人員攜帶合法工具進入。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯降低。不是消除。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "是。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "21:05。千田看著螢幕上的鏡島圖。他的手指點在緊急維護入口的位置。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "這個入口。我設計底層的時候——知道它存在。它不是後門。是合法的緊急通道。消防。設備故障。斷電恢復。都需要它。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "但合法通道——也是能被利用的通道。差別只在——誰拿著卡。誰帶著載體。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）合法通道。合法用途。合法承包。每一層都是合法的。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上的鏡島圖還亮著。緊急維護入口的標記。幾條線路。幾個入口。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是疊起來——缺失載體。無借出。無工作單。共享臨時卡。不綁定人員。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手指碰了一下桌面的邊緣。很輕。像在確認什麼是實的。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）每一層單獨看都是正常的。疊起來——就是一條能重新打開鏡島的路。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "21:10。日下部把所有資料收進證物袋。封存。編號。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "缺失載體追查。正式轉入刑事程序。硬體序號。attestation。美空節點。維護入口。共享臨時卡。全部列入。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著澪。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "下一步——當輪系統確認。G07／03。家屬資料建立的 provisional mapping。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯美空。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "如果當輪系統正式確認——就不是 provisional 了。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著他。她的臉很疲憊。眼下很深。但她的眼睛沒有閃避。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯好。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "21:12。小會議室。螢幕上的鏡島圖還亮著。緊急維護入口的標記。銀色外殼的庫存影像。便衣截圖。兩組並排。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "同一個形制。同一個型號。不能證明同一個序號。不能證明現在在誰手裡。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）銀色外殼。千田交給我的那個。第一輪。電車上。他壓著肋下。血。他說不要救東京。那個外殼——沒有跟回來。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上的庫存影像還亮著。薄銀色。防靜電。雙卡扣。細長指示窗。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是它的形制——跟缺失載體一樣。跟美空節點出現過的 attestation 一樣。同一條鏈。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "證物袋一個一個封好。編號貼上去。金屬扣的聲音很輕。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）千田從安全庫拿出來。交給我。我沒有守住。然後——某一輪——它出現在美空的醫療節點。沒有借出。沒有工作單。然後——它不見了。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "桌面上的證物袋排成一列。銀色外殼的影像還留在螢幕角落。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）現在——它可能在哪裡。可能在一個合法技師的工具箱裡。可能在某個維護人員的口袋裡。也可能——", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手放在桌面。指尖很涼。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不。現在不能想那個。現在——證據只到這裡。同型。高概率。無借出。無工作單。未歸還。其餘的——明天。", background: Background.Chapter_22_Ch22_Act7_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "21:15。小會議室。螢幕暗了。證物袋封好了。日下部站起來。千田站起來。指定專家收起筆電。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪最後看了一眼螢幕。銀色外殼的影像已經被收進檔案。只剩桌面。空的。", background: Background.Chapter_22_Ch22_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約三日八小時五十八分鐘。", background: Background.Chapter_22_Ch22_Act7_S0 },
];
